begin;
alter table public.apostolic_building_catalog drop constraint apostolic_building_catalog_building_check;
alter table public.apostolic_building_catalog add constraint apostolic_building_catalog_building_check check(building in('town_hall','warehouse','farm','lumberyard','quarry','olive_press','market','academy'));
alter table public.apostolic_city_buildings drop constraint apostolic_city_buildings_building_check;
alter table public.apostolic_city_buildings add constraint apostolic_city_buildings_building_check check(building in('town_hall','warehouse','farm','lumberyard','quarry','olive_press','market','academy'));
insert into public.apostolic_building_catalog(building,name,description,base_duration_seconds,base_costs,sort_order)values('academy','Academia','Desbloqueia a árvore tecnológica.',100,'{"cedar":80,"stone":80,"oil":45,"gold":55}',8);
insert into public.apostolic_city_buildings(city_id,building,level)select id,'academy',1 from public.apostolic_cities on conflict do nothing;
create or replace function public.apostolic_add_academy_to_city()returns trigger language plpgsql security definer set search_path=''as $$begin insert into public.apostolic_city_buildings(city_id,building,level)values(new.id,'academy',1)on conflict do nothing;return new;end;$$;
create trigger apostolic_city_academy_after_insert after insert on public.apostolic_cities for each row execute function public.apostolic_add_academy_to_city();
create table public.apostolic_research_catalog(code text primary key,branch text not null,name text not null,description text not null,tier smallint not null,prerequisites text[]not null default'{}',academy_level smallint not null,base_costs jsonb not null check(not(base_costs?'gems')),duration_seconds integer not null,effect jsonb not null default'{}',sort_order smallint unique);
insert into public.apostolic_research_catalog values
('fertile_fields','stewardship','Campos Férteis','Trigo +10%.',1,'{}',1,'{"oil":30,"gold":40}',90,'{"resource":"wheat","percent":10}',1),('cedar_craft','stewardship','Ofício do Cedro','Cedro +10%.',1,'{}',1,'{"oil":30,"gold":40}',90,'{"resource":"cedar","percent":10}',2),('stone_masonry','stewardship','Cantaria','Pedra +10%.',2,'{cedar_craft}',2,'{"oil":55,"gold":70}',150,'{"resource":"stone","percent":10}',3),('olive_wisdom','stewardship','Sabedoria das Oliveiras','Azeite +10%.',2,'{fertile_fields}',2,'{"oil":50,"gold":75}',150,'{"resource":"oil","percent":10}',4),('fair_measures','commerce','Pesos Justos','Prepara comércio seguro.',1,'{}',1,'{"oil":40,"gold":60}',120,'{}',5),('caravan_routes','logistics','Rotas de Caravana','Desbloqueia caravanas.',2,'{fair_measures}',2,'{"oil":70,"gold":100}',210,'{"unlock":"caravans"}',6),('watchtowers','defense','Torres de Vigia','Desbloqueia guarnições.',2,'{stone_masonry}',2,'{"stone":100,"oil":60,"gold":90}',240,'{"unlock":"garrisons"}',7),('siege_engineering','defense','Engenharia de Cerco','Prepara cercos ligados à Arena.',3,'{watchtowers,caravan_routes}',3,'{"stone":180,"oil":120,"gold":180}',360,'{"unlock":"sieges"}',8);
create table public.apostolic_city_research(city_id uuid references public.apostolic_cities(id)on delete cascade,research_code text references public.apostolic_research_catalog(code),completed_at timestamptz default now(),primary key(city_id,research_code));
create table public.apostolic_research_queue(id uuid primary key default gen_random_uuid(),city_id uuid references public.apostolic_cities(id)on delete cascade,research_code text references public.apostolic_research_catalog(code),costs jsonb not null,started_at timestamptz default clock_timestamp(),finishes_at timestamptz not null,status text not null default'researching'check(status in('researching','completed')),idempotency_key uuid not null,completed_at timestamptz,unique(city_id,idempotency_key));
create unique index apostolic_research_one_active_idx on public.apostolic_research_queue(city_id)where status='researching';
alter table public.apostolic_research_catalog enable row level security;alter table public.apostolic_city_research enable row level security;alter table public.apostolic_research_queue enable row level security;
create policy apostolic_research_catalog_read on public.apostolic_research_catalog for select to authenticated using(true);create policy apostolic_city_research_self on public.apostolic_city_research for select to authenticated using(exists(select 1 from public.apostolic_cities c where c.id=city_id and c.owner_id=(select auth.uid())));create policy apostolic_research_queue_self on public.apostolic_research_queue for select to authenticated using(exists(select 1 from public.apostolic_cities c where c.id=city_id and c.owner_id=(select auth.uid())));
revoke all on public.apostolic_research_catalog,public.apostolic_city_research,public.apostolic_research_queue from anon,authenticated;grant select on public.apostolic_research_catalog,public.apostolic_city_research,public.apostolic_research_queue to authenticated;
create or replace function public.apostolic_get_research_center()returns jsonb language sql stable security definer set search_path=''as $$with own as(select id from public.apostolic_cities where owner_id=(select auth.uid())),a as(select level from public.apostolic_city_buildings where city_id=(select id from own)and building='academy')select jsonb_build_object('academy_level',coalesce((select level from a),0),'queue',(select to_jsonb(q)from(select research_code,finishes_at from public.apostolic_research_queue where city_id=(select id from own)and status='researching'limit 1)q),'researches',(select jsonb_agg(jsonb_build_object('code',c.code,'branch',c.branch,'name',c.name,'description',c.description,'tier',c.tier,'academy_level',c.academy_level,'costs',c.base_costs,'duration_seconds',c.duration_seconds,'completed',exists(select 1 from public.apostolic_city_research r where r.city_id=(select id from own)and r.research_code=c.code),'unlocked',coalesce((select level from a),0)>=c.academy_level and not exists(select 1 from unnest(c.prerequisites)p where not exists(select 1 from public.apostolic_city_research r where r.city_id=(select id from own)and r.research_code=p)))order by c.sort_order)from public.apostolic_research_catalog c))$$;
create or replace function public.apostolic_start_research(p_code text,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare cid uuid;cat public.apostolic_research_catalog%rowtype;al smallint;r record;cost bigint;begin select id into cid from public.apostolic_cities where owner_id=(select auth.uid())for update;if cid is null then raise exception'city not found';end if;if exists(select 1 from public.apostolic_research_queue where city_id=cid and status='researching')then raise exception'queue occupied';end if;select*into cat from public.apostolic_research_catalog where code=p_code;select level into al from public.apostolic_city_buildings where city_id=cid and building='academy';if cat.code is null or al<cat.academy_level or exists(select 1 from unnest(cat.prerequisites)p where not exists(select 1 from public.apostolic_city_research x where x.city_id=cid and x.research_code=p))then raise exception'research locked';end if;for r in select key,value from jsonb_each_text(cat.base_costs)loop cost:=r.value::bigint;if not exists(select 1 from public.apostolic_city_resources where city_id=cid and resource=r.key and amount>=cost)then raise exception'insufficient resource';end if;end loop;for r in select key,value from jsonb_each_text(cat.base_costs)loop cost:=r.value::bigint;update public.apostolic_city_resources set amount=amount-cost where city_id=cid and resource=r.key;insert into public.apostolic_resource_ledger(city_id,resource,delta,balance_after,reason,idempotency_key)select cid,r.key,-cost,amount,'research:'||p_code,p_idempotency_key from public.apostolic_city_resources where city_id=cid and resource=r.key;end loop;insert into public.apostolic_research_queue(city_id,research_code,costs,finishes_at,idempotency_key)values(cid,p_code,cat.base_costs,clock_timestamp()+make_interval(secs=>cat.duration_seconds),p_idempotency_key);return public.apostolic_get_research_center();end;$$;
create or replace function public.apostolic_finish_research()returns jsonb language plpgsql security definer set search_path=''as $$declare cid uuid;q public.apostolic_research_queue%rowtype;cat public.apostolic_research_catalog%rowtype;res text;pct integer;begin select id into cid from public.apostolic_cities where owner_id=(select auth.uid())for update;select*into q from public.apostolic_research_queue where city_id=cid and status='researching'for update;if not found then return public.apostolic_get_research_center();end if;if q.finishes_at>clock_timestamp()then raise exception'in progress';end if;select*into cat from public.apostolic_research_catalog where code=q.research_code;insert into public.apostolic_city_research values(cid,q.research_code,now())on conflict do nothing;update public.apostolic_research_queue set status='completed',completed_at=now()where id=q.id;res:=cat.effect->>'resource';pct:=coalesce((cat.effect->>'percent')::integer,0);if res is not null then update public.apostolic_city_resources set production_per_hour=production_per_hour+greatest(1,ceil(production_per_hour*pct/100.0)::integer)where city_id=cid and resource=res;end if;return public.apostolic_get_research_center();end;$$;
revoke all on function public.apostolic_get_research_center(),public.apostolic_start_research(text,uuid),public.apostolic_finish_research()from public;grant execute on function public.apostolic_get_research_center(),public.apostolic_start_research(text,uuid),public.apostolic_finish_research()to authenticated;commit;
